function ltv(arpu, grossMargin, churnRate){ arpu=+arpu; grossMargin=+grossMargin; churnRate=+churnRate; if(churnRate<=0) return Infinity; return arpu*grossMargin/churnRate; }
function ltvSimple(arpu, churnRate){ return ltv(arpu,1,churnRate); }
function ratio(ltvVal, cac){ cac=+cac; if(cac<=0) return Infinity; return ltvVal/cac; }
var EXPORTS={ltv:ltv, ltvSimple:ltvSimple, ratio:ratio};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LtvForgePure = EXPORTS; }
